using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad]public static class TrailClueMarkerReview {
 const string E="Evidence/trail-clue-marker-20261030/",D="Assets/Demo/Environment/ObjectiveTrails/";
 static TrailClueMarkerReview(){EditorApplication.delayCall+=Build;}
 static void Build(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"built.txt"))return;Directory.CreateDirectory(E);var scene=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueSettlement_HunterTrails.unity");File.Copy(scene.path,E+"scene-before.unity.txt",true);var clue=Object.FindObjectsOfType<DemoInteractable>().First(t=>t.clueId=="trail");var root=clue.gameObject;root.name="Trail clue - discarded shield and gold marker";root.transform.localScale=Vector3.one;root.GetComponent<Renderer>().enabled=false;var box=root.GetComponent<BoxCollider>();box.center=new Vector3(0,.85f,0);box.size=new Vector3(1.65f,2.05f,1.65f);box.isTrigger=true;clue.evidenceText="Evidence: a discarded shield and broken strap lie beside deep drag marks leading east into the pines.";
 var shield=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Viking Village/Prefabs/Props/pf_shield_03.prefab"));shield.name="Discarded shield - trail evidence";shield.transform.SetParent(root.transform,false);shield.transform.localPosition=Vector3.zero;shield.transform.localRotation=Quaternion.Euler(58,12,-18);shield.transform.localScale=Vector3.one*1.35f;foreach(var t in shield.GetComponentsInChildren<Transform>(true)){t.gameObject.layer=0;GameObjectUtility.SetStaticEditorFlags(t.gameObject,0);GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);}foreach(var col in shield.GetComponentsInChildren<Collider>())Object.DestroyImmediate(col);var rs=shield.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);var terrain=Object.FindObjectOfType<Terrain>();shield.transform.position+=Vector3.up*(terrain.SampleHeight(root.transform.position)+terrain.transform.position.y+.03f-b.min.y);
 var badge=new GameObject("Gold diamond - drag clue").transform;badge.SetParent(root.transform,false);badge.localPosition=new Vector3(0,1.7f,0);var diamond=GameObject.CreatePrimitive(PrimitiveType.Cube);diamond.name="Gold clue diamond";diamond.transform.SetParent(badge,false);diamond.transform.localRotation=Quaternion.Euler(0,0,45);diamond.transform.localScale=new Vector3(.22f,.22f,.07f);Object.DestroyImmediate(diamond.GetComponent<Collider>());var mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.SetColor("_BaseColor",new Color(1.6f,1.05f,.22f));AssetDatabase.CreateAsset(mat,AssetDatabase.GenerateUniqueAssetPath(D+"TrailClueGold.mat"));diamond.GetComponent<Renderer>().sharedMaterial=mat;
 var label=new GameObject("DRAG CLUE label");label.transform.SetParent(badge,false);label.transform.localPosition=new Vector3(0,.37f,0);var text=label.AddComponent<TextMesh>();text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");label.GetComponent<Renderer>().sharedMaterial=text.font.material;text.text="DRAG CLUE";text.fontSize=52;text.characterSize=.037f;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=new Color(1,.84f,.43f);
 var light=new GameObject("Trail shield small reveal light").AddComponent<Light>();light.transform.SetParent(root.transform,false);light.transform.localPosition=new Vector3(0,1.0f,-.3f);light.type=LightType.Point;light.range=3.5f;light.intensity=1.15f;light.color=new Color(1,.73f,.38f);light.shadows=LightShadows.None;
 var player=Object.FindObjectOfType<HunterTorchPose>();var marker=root.AddComponent<TrailClueMarker>();marker.clue=clue;marker.badge=badge;marker.view=player.GetComponent<DemoMovement>().viewCamera;player.gameObject.AddComponent<TrailClueMarkerProbe>();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(E+"built.txt","scene="+scene.path+" position="+root.transform.position+" source=Assets/Viking Village/Prefabs/Props/pf_shield_03.prefab\nGold diamond + DRAG CLUE camera-facing label; original clueId=trail/range="+clue.range+"; clickable root trigger collider.\n");}
 [MenuItem("Vampire Demo/Finish Trail Clue Marker")]static void Finish(){if(EditorApplication.isPlaying)return;var player=Object.FindObjectOfType<HunterTorchPose>();foreach(var probe in player.GetComponents<TrailClueMarkerProbe>())Object.DestroyImmediate(probe);var scene=player.gameObject.scene;string path=scene.path;EditorSceneManager.SaveScene(scene);EditorSceneManager.OpenScene(path);object[] counts={0,0,0};typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("GetCountsByType",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).Invoke(null,counts);File.WriteAllText(E+"saved.txt","saved and reopened="+path+"; test probe removed; errors="+counts[0]+" warnings="+counts[1]);}
}
